def fun(S):
    MOD = 10**9 + 7
    a_count = b_count = c_count = 0
    for char in S:
        if char == 'a':
            a_count = (2 * a_count + 1) % MOD
        elif char == 'b':
            b_count = (2 * b_count + a_count) % MOD
        elif char == 'c':
            c_count = (2 * c_count + b_count) % MOD
    return c_count
